    "workedSolution": {
     "steps": [
      {
       "title": "Find |AC| with the distance formula",
       "lines": [
        {
         "tex": "|AC| &= \\sqrt{(16-4)^2 + (11-2)^2}"
        },
        {
         "tex": "&= \\sqrt{12^2 + 9^2}"
        },
        {
         "tex": "&= \\sqrt{225}"
        },
        {
         "tex": "&= 15"
        }
       ]
      },
      {
       "title": "Use the ratio 2 : 1",
       "lines": [
        {
         "text": "$|AD| : |DC| = 2 : 1$, so $|AD|$ is $\\frac{2}{3}$ of $|AC|$."
        },
        {
         "tex": "|AD| &= \\frac{2}{3}(15)"
        },
        {
         "tex": "&= 10"
        }
       ]
      }
     ],
     "finalAnswer": "|AD| = 10"
    }
