    "answerStatus": "written",
    "model_source": "scheme",
    "workedSolution": {
     "steps": [
      {
       "title": "Areas change by the scale factor squared",
       "lines": [
        {
         "text": "Lengths are multiplied by $k$, so areas are multiplied by $k^2$."
        },
        {
         "tex": "\\text{Area } PQR &= k^2 \\times \\text{Area } DEF"
        },
        {
         "tex": "18.75 &= 2.5^2 \\times \\text{Area } DEF"
        },
        {
         "tex": "18.75 &= 6.25 \\times \\text{Area } DEF"
        }
       ]
      },
      {
       "title": "Divide both sides by 6.25",
       "lines": [
        {
         "tex": "\\text{Area } DEF &= \\frac{18.75}{6.25}"
        },
        {
         "tex": "&= 3"
        }
       ]
      }
     ],
     "finalAnswer": "\\text{Area } DEF = 3 \\text{ cm}^2"
    }
