     "steps": [
      {
       "title": "Find the distance flown in the air",
       "lines": [
        {
         "text": "Let $h$ be the flight path from $L$. The ground distance $LE = 1250$ m is the side adjacent to the $14^\\circ$ angle."
        },
        {
         "tex": "\\cos 14^\\circ &= \\frac{1250}{h}"
        },
        {
         "tex": "h &= \\frac{1250}{\\cos 14^\\circ}"
        },
        {
         "tex": "&= 1288.267"
        },
        {
         "tex": "&= 1288"
        }
       ]
      },
      {
       "title": "Add the distance on the runway",
       "lines": [
        {
         "tex": "\\text{Total} &= 1250 + 1288"
        },
        {
         "tex": "&= 2538"
        }
       ]
      }
     ],
     "finalAnswer": "2538 \\text{ m}"
